/**
 * transferIcons —— 官方「文件传输中心」用到的图标，**逐字取自官方 bundle**
 * （源码考古报告：`D:\DEEPSEEK\t69-official-transfer-icons.md`）
 *
 * 官方这里混用了 Tabler 与 Lucide 两套图标 + 3 个**本地自定义**矢量：
 *   Zc  → Tabler `outline/loader-2`     （active 转圈）      size 16
 *   Yf  → Tabler `outline/check`        （completed）        size 16 · stroke 1.75
 *   C9e → Tabler `outline/circle-x`     （failed）           size 16 · stroke 1.75
 *   Udi → 本地 20×20 圆环+横杠          （canceled）         size 16
 *   hm/Tw → Lucide `chevron-down`/`chevron-up`             CSS 定 17px
 *   wv  → Lucide `x`                                       CSS 定 16px
 *   HNe → 行内兜底图标：download 类型 = Tabler `outline/download`，其余 = Lucide `cloud-upload`
 *   Rdi → 本地 20×20 带拉链的文档（archive）
 *   Fdi → 本地 12×11 五条竖杠（audio，height = size × 11/12）
 *
 * ⚠️ 官方传 stroke 宽度的 prop 名是 `stroke`（Tabler 封装怪癖），不是 `strokeWidth`。
 * 这里直接写死成属性，避免 Iconify 的默认 2 覆盖。
 */
import type { ReactNode } from 'react';

interface IconProps { className?: string }

/** Tabler 线稿图标外壳（官方 `_ui`：viewBox 24 · fill none · stroke currentColor · round 连接） */
function Tabler({ size = 16, strokeWidth = 2, className, children }: IconProps & { size?: number; strokeWidth?: number; children: ReactNode }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      aria-hidden="true"
    >
      {children}
    </svg>
  );
}

/** 官方 `Zc` = Tabler outline/loader-2（≈3/4 圆弧） */
export function TransferSpinnerIcon({ className }: IconProps) {
  return <Tabler className={className}><path d="M12 3a9 9 0 1 0 9 9" /></Tabler>;
}

/** 官方 `Yf` = Tabler outline/check（stroke 1.75） */
export function TransferDoneIcon({ className }: IconProps) {
  return <Tabler className={className} strokeWidth={1.75}><path d="M5 12l5 5l10 -10" /></Tabler>;
}

/** 官方 `C9e` = Tabler outline/circle-x（stroke 1.75） */
export function TransferFailedIcon({ className }: IconProps) {
  return (
    <Tabler className={className} strokeWidth={1.75}>
      <path d="M12 12m-9 0a9 9 0 1 0 18 0a9 9 0 1 0 -18 0" />
      <path d="M10 10l4 4m0 -4l-4 4" />
    </Tabler>
  );
}

